package narra

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"testing"
)

// The std modules written in Narra live in std/src/ at the repo root. Both
// compilers embed their text: Go through std_sources.go, the self-hosted
// compiler through selfhost/src/stdtext.nra. TestStdSources keeps both
// generated files equal to std/src; NARRA_UPDATE=1 rewrites them.

const (
	stdSourceDir      = "../../../std/src"
	stdSourcesGoPath  = "std_sources.go"
	stdSourcesNraPath = "../../../selfhost/src/stdtext.nra"
)

// readStdSources reads std/src/*.nra as module path -> text.
func readStdSources(t *testing.T) (map[string]string, []string) {
	files, err := filepath.Glob(filepath.Join(stdSourceDir, "*.nra"))
	if err != nil {
		t.Fatal(err)
	}
	texts := map[string]string{}
	var paths []string
	for _, f := range files {
		data, err := os.ReadFile(f)
		if err != nil {
			t.Fatal(err)
		}
		path := "std/" + strings.TrimSuffix(filepath.Base(f), ".nra")
		texts[path] = string(data)
		paths = append(paths, path)
	}
	sort.Strings(paths)
	return texts, paths
}

func stdSourcesGo(texts map[string]string, paths []string) string {
	var b strings.Builder
	b.WriteString("// Code generated by TestStdSources from std/src. DO NOT EDIT.\n")
	b.WriteString("// NARRA_UPDATE=1 go test -run TestStdSources rewrites it.\n\n")
	b.WriteString("package narra\n\n")
	b.WriteString("// stdSources holds the text of each std module written in Narra.\n")
	b.WriteString("var stdSources = map[string]string{\n")
	for _, p := range paths {
		fmt.Fprintf(&b, "\t%q: %s,\n", p, strconv.Quote(texts[p]))
	}
	b.WriteString("}\n")
	return b.String()
}

func stdSourcesNra(t *testing.T, texts map[string]string, paths []string) string {
	var b strings.Builder
	b.WriteString("// Generated by TestStdSources from std/src. Do not edit:\n")
	b.WriteString("// NARRA_UPDATE=1 go test -run TestStdSources rewrites it.\n\n")
	for _, p := range paths {
		fmt.Fprintf(&b, "const %s = %s\n\n", stdConstName(p), narraString(t, texts[p]))
	}
	b.WriteString("// stdSourceFor is the Narra text of a std source module, or \"\" when the\n")
	b.WriteString("// module is a builtin one.\n")
	b.WriteString("export function stdSourceFor(path: string): string {\n")
	for _, p := range paths {
		fmt.Fprintf(&b, "  if (path == %q) {\n    return %s\n  }\n", p, stdConstName(p))
	}
	b.WriteString("  return \"\"\n}\n")
	return b.String()
}

// stdConstName names the constant that holds a std module's text:
// std/option -> STD_OPTION.
func stdConstName(path string) string {
	return strings.ToUpper(strings.ReplaceAll(path, "/", "_"))
}

func TestStdSources(t *testing.T) {
	texts, paths := readStdSources(t)
	files := map[string]string{
		stdSourcesGoPath:  stdSourcesGo(texts, paths),
		stdSourcesNraPath: stdSourcesNra(t, texts, paths),
	}
	for path, want := range files {
		if os.Getenv("NARRA_UPDATE") != "" {
			if err := os.WriteFile(path, []byte(want), 0o644); err != nil {
				t.Fatal(err)
			}
			continue
		}
		got, err := os.ReadFile(path)
		if err != nil {
			t.Fatal(err)
		}
		if string(got) != want {
			t.Errorf("%s is stale (NARRA_UPDATE=1 rewrites it): %s", path, firstDiff(want, string(got)))
		}
	}
	// Every source file is registered, and every registered source module
	// has a file.
	for _, p := range paths {
		if m := stdModules[p]; m == nil || !m.Source {
			t.Errorf("std/src has %s, but no registerSourceModule names it", p)
		}
	}
}
